INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-416.5, 1, 1, 1, 3.414, "カリン", "2030/01/01 14:59:59", "2025/01/31 12:00:00", 0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 190801, 1000001, 62);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-416.5, 1, 1, 2, 3.099, "カリン", "2030/01/01 14:59:59", "2025/01/31 12:00:00", 0, "ミッションをクリアして、\n報酬をゲットしましょう！", 2, 190801, 1000002, 62);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-416.5, 1, 1, 3, 2.801, "カリン", "2030/01/01 14:59:59", "2025/01/31 12:00:00", 0, "受け取ることができる\n報酬があるようです\n確認してみてください", 2, 190801, 1000003, 63);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-416.5, 2, 1, 4, 0, "カリン", "2030/01/01 14:59:59", "2025/01/31 12:00:00", 0, "報酬がもらえますよ！\nチェックしてみてください", 2, 190801, 1000004, 63);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-363, 2, 1, 5, 2.12, "カリン", "2030/01/01 14:59:59", "2025/01/31 12:00:00", 0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 190801, 1000005, 64);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-363, 1, 1, 6, 1.68, "カリン", "2030/01/01 14:59:59", "2025/01/31 12:00:00", 0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, 190801, 1000006, 64);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-363, 2, 1, 7, 2.33, "カリン", "2030/01/01 14:59:59", "2025/01/31 12:00:00", 0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 190801, 1000007, 64);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 3, 10201, 101, 5.18, "ラビリスタ", "2030/01/01 14:59:59", "2025/01/31 12:00:00", -6, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 7, 133701, 1020101, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10201, 201, 8.77, "クリスティーナ", "2030/01/01 14:59:59", "2025/01/31 12:00:00", -2, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 2, 133901, 1020102, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 6, 10201, 301, 15.5, "ネネカ", "2030/01/01 14:59:59", "2025/01/31 12:00:00", 0, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 1, 133801, 1020103, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10202, 101, 9.061, "ランファ", "2030/01/01 14:59:59", "2025/02/28 12:00:00", 0, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 5, 134301, 1020201, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10202, 201, 7.699, "チカ", "2030/01/01 14:59:59", "2025/02/28 12:00:00", 0, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 2, 134401, 1020202, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10203, 101, 8.595, "アオイ", "2030/01/01 14:59:59", "2025/03/31 12:00:00", 0, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 2, 134601, 1020301, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10203, 201, 7.758, "クローチェ", "2030/01/01 14:59:59", "2025/03/31 12:00:00", 0, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 2, 134501, 1020302, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10204, 101, 7, "ルイズマリー", "2030/01/01 14:59:59", "2025/04/30 12:00:00", 0, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 6, 132302, 1020401, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10204, 201, 7.904, "イロハ", "2030/01/01 14:59:59", "2025/04/30 12:00:00", 0, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 2, 132402, 1020402, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10204, 301, 8.487, "ソノ", "2030/01/01 14:59:59", "2025/04/30 12:00:00", 0, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 2, 132502, 1020403, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10205, 101, 8.763, "カノン", "2030/01/01 14:59:59", "2025/05/31 12:00:00", 0, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 2, 134901, 1020502, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10205, 201, 6.417, "ツムギ", "2030/01/01 14:59:59", "2025/05/31 12:00:00", 0, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 3, 134801, 1020503, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 3, 10206, 101, 10.335, "エリス", "2030/01/01 14:59:59", "2025/06/30 12:00:00", 0, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 7, 135001, 1020601, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10206, 201, 6.281, "シェフィ", "2030/01/01 14:59:59", "2025/06/30 12:00:00", 0, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 4, 135101, 1020602, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10206, 301, 12.244, "プレシア", "2030/01/01 14:59:59", "2025/06/30 12:00:00", 0, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 2, 135201, 1020603, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10207, 101, 6.339, "クリア", "2030/01/01 14:59:59", "2025/07/31 12:00:00", 0, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 8, 135301, 1020701, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 7, 10207, 201, 8.184, "アネモネ", "2030/01/01 14:59:59", "2025/07/31 12:00:00", 0, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 9, 135401, 1020702, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 9, 10208, 101, 3.906, "アイラ", "2030/01/01 14:59:59", "2025/08/31 12:00:00", 0, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 2, 129101, 1020801, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10208, 201, 14.465, "シナツ", "2030/01/01 14:59:59", "2025/08/31 12:00:00", 0, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 2, 129201, 1020802, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10208, 301, 8.662, "ヒヨリ", "2030/01/01 14:59:59", "2025/08/31 12:00:00", 0, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 3, 100101, 1020803, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10208, 401, 10.915, "レイ", "2030/01/01 14:59:59", "2025/08/31 12:00:00", 0, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 3, 100301, 1020804, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10209, 101, 6.042, "ユキノ", "2030/01/01 14:59:59", "2025/09/30 12:00:00", 0, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 7, 135802, 1020901, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10209, 201, 9.402, "サツキ", "2030/01/01 14:59:59", "2025/09/30 12:00:00", 0, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 1, 135903, 1020902, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 8, 10209, 301, 8.16, "ルルィ", "2030/01/01 14:59:59", "2025/09/30 12:00:00", 0, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 1, 136902, 1020903, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 3, 10210, 101, 5, "カスミ", "2030/01/01 14:59:59", "2025/10/31 12:00:00", 0, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 2, 137401, 1021001, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10210, 201, 8.12, "アラクネ", "2030/01/01 14:59:59", "2025/10/31 12:00:00", 0, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 1, 136001, 1021002, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10210, 301, 6.386, "ナーナ", "2030/01/01 14:59:59", "2025/10/31 12:00:00", 0, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 2, 136202, 1021003, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 3, 10211, 101, 7.438, "ユイ", "2030/01/01 14:59:59", "2025/11/30 12:00:00", 0, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 4, 136402, 1021101, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10211, 201, 8.35, "ミソラ", "2030/01/01 14:59:59", "2025/11/30 12:00:00", 0, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 5, 136302, 1021102, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10212, 101, 5, "シズル", "2030/01/01 14:59:59", "2025/12/31 12:00:00", 0, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 2, 136501, 1021201, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10212, 201, 5.25, "リノ", "2030/01/01 14:59:59", "2025/12/31 12:00:00", 0, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 2, 137902, 1021202, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10212, 301, 7.5, "ラビリスタ", "2030/01/01 14:59:59", "2025/12/31 12:00:00", 0, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 2, 106801, 1021203, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10213, 101, 8.204, "ライラエル", "2030/01/01 14:59:59", "2026/01/31 12:00:00", 0, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 2, 126501, 1021301, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10213, 201, 7.176, "ネフィ＝ネラ", "2030/01/01 14:59:59", "2026/01/31 12:00:00", 0, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 2, 129701, 1021302, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10213, 301, 8.602, "ヴァイオレット", "2030/01/01 14:59:59", "2026/01/31 12:00:00", 0, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 5, 133101, 1021303, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10213, 102, 10.14, "ライラエル", "2030/01/01 14:59:59", "2026/02/06 12:00:00", 0, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 3, 138101, 1021304, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10213, 202, 10.152, "ネフィ＝ネラ", "2030/01/01 14:59:59", "2026/02/06 12:00:00", 0, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 7, 138201, 1021305, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10213, 302, 9.688, "ヴァイオレット", "2030/01/01 14:59:59", "2026/02/06 12:00:00", 0, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 3, 138001, 1021306, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10213, 401, 5.928, "ペコリーヌ", "2030/01/01 14:59:59", "2026/02/12 12:00:00", 0, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 1, 138301, 1021307, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10214, 101, 9.19, "ワカナ", "2030/01/01 14:59:59", "2026/02/28 12:00:00", 0, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 2, 138702, 1021401, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10214, 201, 8.724, "シオリ", "2030/01/01 14:59:59", "2026/02/28 12:00:00", 0, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 3, 138802, 1021402, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10215, 101, 7.758, "グレイス", "2030/01/01 14:59:59", "2026/03/31 12:00:00", 0, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 1, 138902, 1021501, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 6, 10215, 201, 6.375, "キョウカ", "2030/01/01 14:59:59", "2026/03/31 12:00:00", 0, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 4, 139002, 1021502, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 6, 10215, 301, 6.173, "ルルィ", "2030/01/01 14:59:59", "2026/03/31 12:00:00", 0, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 1, 136902, 1021503, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 6, 10216, 101, 4.202, "ミホ", "2030/01/01 14:59:59", "2026/04/30 12:00:00", 0, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 2, 139202, 1021601, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 6, 10216, 201, 2.842, "マホ", "2030/01/01 14:59:59", "2026/04/30 12:00:00", 0, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 1, 139302, 1021602, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10216, 301, 4.598, "エリカ", "2030/01/01 14:59:59", "2026/04/30 12:00:00", 0, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 1, 139402, 1021603, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10217, 101, 6.533, "リリ", "2030/01/01 14:59:59", "2026/05/31 12:00:00", 0, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 3, 125802, 1021701, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 3, 10217, 301, 5, "プレシア", "2030/01/01 14:59:59", "2026/05/31 12:00:00", 0, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 3, 126102, 1021702, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 3, 10217, 201, 5.214, "クリア", "2030/01/01 14:59:59", "2026/05/31 12:00:00", 0, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 4, 126002, 1021703, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10217, 102, 8.781, "リリ", "2030/01/01 14:59:59", "2026/05/31 12:00:00", 0, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 3, 139501, 1021704, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10217, 202, 6.529, "クリア", "2030/01/01 14:59:59", "2026/05/31 12:00:00", 0, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 1, 139601, 1021705, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 3, 10217, 302, 3.195, "プレシア", "2030/01/01 14:59:59", "2026/05/31 12:00:00", 0, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 2, 139701, 1021706, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10218, 101, 12.43, "ルイズマリー", "2030/01/01 14:59:59", "2026/06/30 12:00:00", 0, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 3, 139902, 1021801, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10218, 201, 6.35, "クレジッタ", "2030/01/01 14:59:59", "2026/06/30 12:00:00", 0, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 3, 140001, 1021802, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10219, 101, 10.23, "フブキ", "2030/01/01 14:59:59", "2026/07/31 12:00:00", 0, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 5, 140102, 1021901, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10219, 201, 5.584, "ヴァンピィ", "2030/01/01 14:59:59", "2026/07/31 12:00:00", 0, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 2, 140201, 1021902, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 6, 10220, 201, 2.8, "クローチェ", "2030/01/01 14:59:59", "2026/08/31 12:00:00", 0, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 3, 126401, 1022001, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10220, 101, 8.9, "ヴルム", "2030/01/01 14:59:59", "2026/08/31 12:00:00", 0, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 3, 127802, 1022002, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10220, 202, 4.49, "クローチェ", "2030/01/01 14:59:59", "2026/08/31 12:00:00", 0, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 1, 140602, 1022003, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10220, 102, 9.42, "ヴルム", "2030/01/01 14:59:59", "2026/08/31 12:00:00", 0, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 3, 140501, 1022004, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 4, 10220, 301, 7, "リーザ", "2030/01/01 14:59:59", "2026/08/31 12:00:00", 0, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 1, 140402, 1022005, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10221, 101, 8.61, "アーモンドアイ", "2030/01/01 14:59:59", "2026/10/31 12:00:00", 0, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 3, 141101, 1022101, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 6, 10221, 201, 3.55, "ラッキーライラック", "2030/01/01 14:59:59", "2026/10/31 12:00:00", 0, "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", 1, 141201, 1022102, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10221, 301, 8.26, "デアリングタクト", "2030/01/01 14:59:59", "2026/10/31 12:00:00", 0, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 1, 141301, 1022103, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10221, 401, 8.79, "ゴールドシップ", "2030/01/01 14:59:59", "2026/10/31 12:00:00", 0, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 1, 141001, 1022104, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10221, 101, 8.61, "アーモンドアイ", "2030/01/01 14:59:59", "2026/10/31 12:00:00", 0, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 3, 141101, 1022105, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 1, 10221, 202, 2.69, "ラッキーライラック", "2030/01/01 14:59:59", "2026/10/31 12:00:00", 0, "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", 2, 141201, 1022106, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10221, 301, 8.26, "デアリングタクト", "2030/01/01 14:59:59", "2026/10/31 12:00:00", 0, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 1, 141301, 1022107, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-285, 2, 10221, 401, 8.79, "ゴールドシップ", "2030/01/01 14:59:59", "2026/10/31 12:00:00", 0, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 1, 141001, 1022108, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-416.5, 1, 2, 1, 3.414, "カリン", "2030/01/01 14:59:59", "2026/04/10 12:00:00", 0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 190805, 2000001, 62);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-416.5, 1, 2, 2, 3.099, "カリン", "2030/01/01 14:59:59", "2026/04/10 12:00:00", 0, "ミッションをクリアして、\n報酬をゲットしましょう！", 2, 190805, 2000002, 62);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-416.5, 1, 2, 3, 2.801, "カリン", "2030/01/01 14:59:59", "2026/04/10 12:00:00", 0, "受け取ることができる\n報酬があるようです\n確認してみてください", 2, 190805, 2000003, 63);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-416.5, 2, 2, 4, 0, "カリン", "2030/01/01 14:59:59", "2026/04/10 12:00:00", 0, "報酬がもらえますよ！\nチェックしてみてください", 2, 190805, 2000004, 63);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-363, 2, 2, 5, 2.12, "カリン", "2030/01/01 14:59:59", "2026/04/10 12:00:00", 0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 190805, 2000005, 64);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-363, 1, 2, 6, 1.68, "カリン", "2030/01/01 14:59:59", "2026/04/10 12:00:00", 0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, 190805, 2000006, 64);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (-363, 2, 2, 7, 2.33, "カリン", "2030/01/01 14:59:59", "2026/04/10 12:00:00", 0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 190805, 2000007, 64);
